export interface GastronomyShowroom {
  destroy(): void;
  goToRoom(preset: RoomPreset): void;
  getRoomManifest(preset?: RoomPreset): ShowroomAiManifest;
  applyRoomConcept(preset: RoomPreset, patch: RoomConceptPatch): RoomConceptResult;
}

export interface ShowroomAiManifestPreset {
  id: RoomPreset;
  label: string;
  theme: ShowroomTheme;
  themeLabel: string;
}

export interface ShowroomAiManifestFurnishing {
  id: string;
  label: string;
  category: FurnishingObject["category"];
}

export interface ShowroomAiManifestStructureSlot {
  wall: FreestandingWall;
  index: number;
  enabled: boolean;
}

// One entry per wall/zone that actually exists in the current room preset
// (not every preset has a counter, a partition, etc.) — label is the same
// contextual, human-readable name (e.g. "Videowall & Neuheiten",
// "Empfang & Concierge-Wand") the manual editor already shows, not the
// internal wall id, so both the wizard's wall-picker cards and the chat
// assistant can present/reference walls the way a customer would.
export interface ShowroomAiManifestDisplayWall {
  wall: DisplayWall;
  label: string;
  enabled: boolean;
  unitCount: number;
  size: DisplaySize | null;
}

export interface ShowroomAiManifest {
  presets: ShowroomAiManifestPreset[];
  selectedPreset: RoomPreset;
  furnishings: ShowroomAiManifestFurnishing[];
  displayWalls: ShowroomAiManifestDisplayWall[];
  structureSlots: ShowroomAiManifestStructureSlot[];
}

export interface RoomConceptFurnishingPatch {
  id: string;
  visible?: boolean;
  positionX?: number;
  positionZ?: number;
  rotationY?: number;
  scaleMultiplier?: number;
  color?: string | null;
}

export interface RoomConceptDisplayContentPatch {
  wall: DisplayWall;
  displayIndex: number;
  composition: DisplayContentComposition;
}

// Säulen/Stelen (totems/steles) are a fixed pool of 4 pre-positioned slots
// per wall type (index 0-3), not a free-form list — "adding" one means
// enabling an existing disabled slot, matching the manual UI's own
// structureCreateHandler behaviour. Variant is intentionally not
// AI-settable: changing it can flip which wall ("totem" vs "stele") a slot
// belongs to and needs dimension-reset handling this pass doesn't cover.
export interface RoomConceptStructurePatch {
  wall: FreestandingWall;
  index: number;
  enabled?: boolean;
  positionX?: number;
  positionZ?: number;
  rotationY?: number;
  color?: string | null;
}

// Sets displayCount/displaySize on the currently-selected wall's
// installation — the exact fields the manual "Displaygrösse"/"Anordnung"
// buttons already write via persistSelectedInstallation(), just invoked
// directly instead of through a click handler.
export interface RoomConceptDisplayLayoutPatch {
  displayCount?: number;
  displaySize?: DisplaySize;
}

// One toggle per wall — on/off plus a coarse size, not a raw inch value or
// an LED-vs-Display technology choice. Technology is deliberately not
// settable here: it's picked automatically from size (see applyRoomConcept),
// the same "auto" behaviour the manual editor already falls back to above
// LED_AUTO_THRESHOLD_INCHES — a customer decides how big and impactful a
// wall should be, not which panel technology renders it.
export interface RoomConceptWallDisplayPatch {
  wall: DisplayWall;
  enabled: boolean;
  size?: "small" | "medium" | "large";
}

// Shows the real (already-working) partner-content rendering mechanic on
// one display — a preview, not a live cross-business connection (see
// docs/showroom-funnel.md). Reuses the existing NETWORK_MATCHES/
// NETWORK_PARTNER_PROFILES tables and marks the pair "approved" in the
// existing per-browser localStorage state, same as the manual network
// panel's own "Demo-Freigabe bestätigen" action.
export interface RoomConceptNetworkPreviewPatch {
  wall: DisplayWall;
  displayIndex: number;
  enabled: boolean;
}

export interface RoomConceptPatch {
  roomSize?: RoomSize;
  light?: LightPreset;
  brightness?: number;
  surfaces?: Partial<Record<RoomSurface, string | null>>;
  floorFinish?: FloorFinish;
  furnishings?: RoomConceptFurnishingPatch[];
  structures?: RoomConceptStructurePatch[];
  displayContent?: RoomConceptDisplayContentPatch[];
  displayLayout?: RoomConceptDisplayLayoutPatch;
  wallDisplays?: RoomConceptWallDisplayPatch[];
  networkPreview?: RoomConceptNetworkPreviewPatch;
}

export interface RoomConceptResult {
  applied: boolean;
  degradedFurnishingIds: string[];
  clampedFurnishingIds: string[];
  degradedStructureKeys: string[];
  clampedStructureKeys: string[];
}

