const STANDARD_DISPLAY_SIZE = 55 as const;
const SCENE_UNITS_PER_METRE = 2;
const DISPLAY_SIZES = [22, 24, 27, 32, 55, 65, 75] as const;
const DISPLAY_SIZE_DIMENSIONS: Record<
  DisplaySize,
  { diagonal: number; width: number; height: number }
> = {
  22: { diagonal: 56, width: 49, height: 27 },
  24: { diagonal: 61, width: 53, height: 30 },
  27: { diagonal: 69, width: 60, height: 34 },
  32: { diagonal: 81, width: 71, height: 40 },
  55: { diagonal: 140, width: 121, height: 68 },
  65: { diagonal: 165, width: 144, height: 81 },
  75: { diagonal: 191, width: 166, height: 93 },
};
const DISPLAY_POSITION_GRID = 0.12;
const DISPLAY_COLLISION_GAP = 0.08;
// Keep wall-mounted screens in front of decorative wall build-ups such as
// slats, frames and shallow columns. The value equals a 15 cm mounting zone.
const DISPLAY_WALL_CLEARANCE = 0.3;
const MIN_DISPLAY_WIDTH_SCALE = 0.35;
const MAX_DISPLAY_WIDTH_SCALE = 4;
const LED_AUTO_THRESHOLD_INCHES = 75;
const LED_MODULE_SIZE_CM = 25;
const LED_CABINET_SIZE_CM = 50;
const DISPLAY_ACCENT = 0xff1748;
const DISPLAY_BEZEL = 0x59091a;
const LED_ACCENT = 0x28e57f;
const LED_BEZEL = 0x063a23;
const WALL_HEIGHT_CM = 310;
const OPENING_WALL_MARGIN_CM = 20;
const WINDOW_MIN_WIDTH_CM = 50;
const WINDOW_MIN_HEIGHT_CM = 50;
