const normalizeDisplaySize = (value: unknown): DisplaySize => {
  const numeric = Number(value);
  if (DISPLAY_SIZES.includes(numeric as DisplaySize)) {
    return numeric as DisplaySize;
  }
  if (!Number.isFinite(numeric)) return STANDARD_DISPLAY_SIZE;
  return DISPLAY_SIZES.reduce((closest, candidate) => (
    Math.abs(candidate - numeric) < Math.abs(closest - numeric)
      ? candidate
      : closest
  ), STANDARD_DISPLAY_SIZE);
};

const getDisplaySizeLabel = (size: DisplaySize): string => {
  const dimensions = DISPLAY_SIZE_DIMENSIONS[size];
  return `${size}″ · ${dimensions.width} × ${dimensions.height} cm`;
};

interface DisplayPhysicalDesign {
  technology: DisplayTechnology;
  requestedTechnology: DisplayTechnologyPreference;
  automaticLED: boolean;
  diagonalInches: number;
  targetWidthCm: number;
  targetHeightCm: number;
  widthCm: number;
  heightCm: number;
  moduleColumns: number;
  moduleRows: number;
  moduleCount: number;
  cabinetColumns: number;
  cabinetRows: number;
  cabinetCount: number;
}

const normalizeDisplayTechnology = (
  value: unknown,
): DisplayTechnologyPreference => (
  value === "display" || value === "led" ? value : "auto"
);

const getDisplayPhysicalDesign = (
  size: DisplaySize,
  orientation: DisplayOrientation,
  widthScale = 1,
  requestedTechnology: DisplayTechnologyPreference = "auto",
): DisplayPhysicalDesign => {
  const dimensions = DISPLAY_SIZE_DIMENSIONS[size];
  const normalizedScale = normalizeDisplayWidthScale(widthScale);
  const landscape = orientation === "landscape";
  const targetWidthCm =
    (landscape ? dimensions.width : dimensions.height) * normalizedScale;
  const targetHeightCm =
    (landscape ? dimensions.height : dimensions.width) * normalizedScale;
  const diagonalInches = size * normalizedScale;
  const automaticLED = diagonalInches > LED_AUTO_THRESHOLD_INCHES + 0.001;
  const normalizedTechnology =
    normalizeDisplayTechnology(requestedTechnology);
  const technology: DisplayTechnology =
    automaticLED || normalizedTechnology === "led" ? "led" : "display";
  if (technology === "display") {
    return {
      technology,
      requestedTechnology: normalizedTechnology,
      automaticLED,
      diagonalInches,
      targetWidthCm,
      targetHeightCm,
      widthCm: targetWidthCm,
      heightCm: targetHeightCm,
      moduleColumns: 0,
      moduleRows: 0,
      moduleCount: 0,
      cabinetColumns: 0,
      cabinetRows: 0,
      cabinetCount: 0,
    };
  }
  const moduleColumns = Math.max(
    1,
    Math.ceil(targetWidthCm / LED_MODULE_SIZE_CM),
  );
  const moduleRows = Math.max(
    1,
    Math.ceil(targetHeightCm / LED_MODULE_SIZE_CM),
  );
  const cabinetColumns = Math.ceil(
    moduleColumns * LED_MODULE_SIZE_CM / LED_CABINET_SIZE_CM,
  );
  const cabinetRows = Math.ceil(
    moduleRows * LED_MODULE_SIZE_CM / LED_CABINET_SIZE_CM,
  );
  return {
    technology,
    requestedTechnology: normalizedTechnology,
    automaticLED,
    diagonalInches,
    targetWidthCm,
    targetHeightCm,
    widthCm: moduleColumns * LED_MODULE_SIZE_CM,
    heightCm: moduleRows * LED_MODULE_SIZE_CM,
    moduleColumns,
    moduleRows,
    moduleCount: moduleColumns * moduleRows,
    cabinetColumns,
    cabinetRows,
    cabinetCount: cabinetColumns * cabinetRows,
  };
};

const getSeamlessLEDPhysicalDesign = (
  widthScene: number,
  heightScene: number,
): DisplayPhysicalDesign => {
  const widthCm = widthScene / SCENE_UNITS_PER_METRE * 100;
  const heightCm = heightScene / SCENE_UNITS_PER_METRE * 100;
  const moduleColumns = Math.max(
    1,
    Math.ceil(widthCm / LED_MODULE_SIZE_CM),
  );
  const moduleRows = Math.max(
    1,
    Math.ceil(heightCm / LED_MODULE_SIZE_CM),
  );
  const cabinetColumns = Math.ceil(
    moduleColumns * LED_MODULE_SIZE_CM / LED_CABINET_SIZE_CM,
  );
  const cabinetRows = Math.ceil(
    moduleRows * LED_MODULE_SIZE_CM / LED_CABINET_SIZE_CM,
  );
  return {
    technology: "led",
    requestedTechnology: "led",
    automaticLED: false,
    diagonalInches: Math.hypot(widthCm, heightCm) / 2.54,
    targetWidthCm: widthCm,
    targetHeightCm: heightCm,
    widthCm,
    heightCm,
    moduleColumns,
    moduleRows,
    moduleCount: moduleColumns * moduleRows,
    cabinetColumns,
    cabinetRows,
    cabinetCount: cabinetColumns * cabinetRows,
  };
};

const getDisplaySceneDimensions = (
  size: DisplaySize,
  orientation: DisplayOrientation,
  widthScale = 1,
  technology: DisplayTechnologyPreference = "auto",
): { width: number; height: number } => {
  const design = getDisplayPhysicalDesign(
    size,
    orientation,
    widthScale,
    technology,
  );
  return {
    width: design.widthCm / 50,
    height: design.heightCm / 50,
  };
};

const getDisplayWidthScaleLabel = (
  size: DisplaySize,
  orientation: DisplayOrientation,
  scale: number,
  technology: DisplayTechnologyPreference = "auto",
): string => {
  const design = getDisplayPhysicalDesign(
    size,
    orientation,
    scale,
    technology,
  );
  return `${Math.round(design.widthCm)} × ${
    Math.round(design.heightCm)
  } cm · ${
    normalizeDisplayWidthScale(scale).toFixed(2).replace(".", ",")
  }×`;
};

const normalizeDisplayWidthScale = (value: unknown): number => {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return 1;
  return Math.round(
    clamp(numeric, MIN_DISPLAY_WIDTH_SCALE, MAX_DISPLAY_WIDTH_SCALE) * 100,
  ) / 100;
};

