function getTotemDisplayLimit(variant: TotemVariant): 2 | 4 {
  return (
    variant === "twoSided"
    || variant === "halfTotem"
    || variant === "midStele"
  ) ? 2 : 4;
}

function getTotemDisplayLayers(variant: TotemVariant): 1 | 2 | 3 {
  if (variant === "midColumn" || variant === "midStele") return 2;
  if (variant === "ceilingColumn" || variant === "twoSided") return 3;
  return 1;
}

function getColumnDisplayRowLimit(
  variant: TotemVariant,
  orientation: DisplayOrientation,
): number {
  const heightLevel = getTotemDisplayLayers(variant);
  return orientation === "portrait"
    ? Math.min(3, heightLevel)
    : Math.min(6, heightLevel * 2);
}

function isSteleVariant(variant: TotemVariant): boolean {
  return (
    variant === "halfTotem"
    || variant === "midStele"
    || variant === "twoSided"
  );
}
