function getDisplayStories(
  preset: RoomPreset,
  content: ContentPreset,
): string[] {
  if (preset === "takeaway" || preset === "restaurant" || preset === "cafe") {
    return GASTRONOMY_DISPLAY_STORIES[preset][content];
  }
  if (preset === "beautySalon" || preset === "barber" || preset === "physio") {
    return BEAUTY_DISPLAY_STORIES[preset][content];
  }
  if (preset === "cinema" || preset === "museum" || preset === "eventHall") {
    return CULTURE_DISPLAY_STORIES[preset][content];
  }
  if (preset === "outdoorShop" || preset === "mountainStation" || preset === "fitnessCenter") {
    return SPORT_DISPLAY_STORIES[preset][content];
  }
  if (preset === "fashionStore" || preset === "electronicsStore" || preset === "shoppingMall") {
    return RETAIL_DISPLAY_STORIES[preset][content];
  }
  if (preset === "corporateLobby" || preset === "corporateMeeting" || preset === "corporateCanteen") {
    return CORPORATE_DISPLAY_STORIES[preset][content];
  }
  if (preset === "hotelLobby" || preset === "spaWellness" || preset === "guestSuite") {
    return HOSPITALITY_DISPLAY_STORIES[preset][content];
  }
  if (preset === "clinicReception" || preset === "waitingTreatment" || preset === "careCenter") {
    return HEALTH_DISPLAY_STORIES[preset][content];
  }
  if (preset === "campusFoyer" || preset === "classroom" || preset === "libraryZone") {
    return EDUCATION_DISPLAY_STORIES[preset][content];
  }
  if (preset === "productionHall" || preset === "logisticsCenter" || preset === "industrialControl") {
    return INDUSTRY_DISPLAY_STORIES[preset][content];
  }
  if (preset === "realEstateLounge" || preset === "modelApartment" || preset === "brandShowroom") {
    return REALESTATE_DISPLAY_STORIES[preset][content];
  }
  return MOBILITY_DISPLAY_STORIES[preset][content];
}

