const PARTITION_FURNISHING_IDS: Partial<
  Record<RoomPreset, Partial<Record<PartitionWall, string>>>
> = {
  restaurant: {
    partition1: "room-divider",
  },
  museum: {
    partition1: "museum-partition-1",
    partition2: "museum-partition-2",
  },
};
const getModularPartitionSlots = (
  preset: RoomPreset,
): ModularPartitionSlot[] => {
  const reservedWalls = new Set<PartitionWall>(
    Object.keys(PARTITION_FURNISHING_IDS[preset] ?? {}) as PartitionWall[],
  );
  const designed = ROOM_PARTITION_PROFILES[preset] ?? [];
  const slots: ModularPartitionSlot[] = designed.slice(0, 2).map(
    (design, index) => ({
      wall: index === 0 ? "partition1" : "partition2",
      design,
      initiallyVisible: true,
    }),
  );
  PARTITION_WALLS.forEach((wall, index) => {
    if (reservedWalls.has(wall) || slots.some((slot) => slot.wall === wall)) {
      return;
    }
    slots.push({
      wall,
      initiallyVisible: false,
      design: {
        label: index === 0
          ? "Flexible Trennwand"
          : "Flexible Trennwand mit Durchgang",
        position: index === 0 ? [-2.6, 5.4] : [2.8, 7.6],
        rotationY: index === 0 ? 0.12 : -0.18,
        width: index === 0 ? 5.2 : 5.8,
        height: 3.2,
        door: index === 0 ? "none" : "single",
        displayCount: 0,
        content: index === 0 ? "campaign" : "pickup",
      },
    });
  });
  return slots.sort((first, second) => (
    PARTITION_WALLS.indexOf(first.wall) - PARTITION_WALLS.indexOf(second.wall)
  ));
};
