function createStructureSlots(
  primaryPosition: [number, number],
  variant: TotemVariant,
): StructureInstanceConfiguration[] {
  const [baseX, baseZ] = primaryPosition;
  const side = baseX < 0 ? -1 : 1;
  const candidates: Array<[number, number]> = [
    [baseX, baseZ],
    [side * 4.35, baseZ < 2.6 ? 4.15 : 1.15],
    [side * 1.55, 4.15],
    [side * 1.55, 1.15],
  ];
  const dimensions = STRUCTURE_DIMENSIONS_CM[variant];
  return candidates.map((position, index) => ({
      position,
      // Every newly added structure starts with its display face towards the
      // default showroom camera. The user can rotate it afterwards.
      rotationY: 0,
      variant,
      displayRows: getTotemDisplayLayers(variant),
      enabled: index === 0,
      shape: "rectangular",
      widthCm: dimensions.widthCm,
      heightCm: dimensions.heightCm,
      depthCm: dimensions.depthCm,
      diameterCm: dimensions.widthCm,
    }));
}

function isFreestandingWall(wall: DisplayWall): wall is FreestandingWall {
  return wall === "totem" || wall === "stele";
}

function isPartitionWall(wall: DisplayWall): wall is PartitionWall {
  return wall === "partition1" || wall === "partition2";
}

function isRightSideWall(wall: DisplayWall): wall is RightSideWall {
  return (RIGHT_SIDE_WALLS as readonly DisplayWall[]).includes(wall);
}

function isLeftSideWall(wall: DisplayWall): wall is LeftSideWall {
  return (LEFT_SIDE_WALLS as readonly DisplayWall[]).includes(wall);
}

function isSideWall(wall: DisplayWall): wall is SideWall {
  return isRightSideWall(wall) || isLeftSideWall(wall);
}

function getSideWallZoneIndex(wall: DisplayWall): number {
  const rightIndex = (RIGHT_SIDE_WALLS as readonly DisplayWall[]).indexOf(wall);
  if (rightIndex >= 0) return rightIndex;
  const leftIndex = (LEFT_SIDE_WALLS as readonly DisplayWall[]).indexOf(wall);
  return Math.max(0, leftIndex);
}

function getSideWallForZone(
  side: "left" | "right",
  zone: number,
): DisplayWall {
  return (
    side === "right"
      ? RIGHT_SIDE_WALLS[clamp(zone, 0, 3)]
      : LEFT_SIDE_WALLS[clamp(zone, 0, 3)]
  );
}

function createEnabledObjects(): Record<DisplayWall, boolean> {
  return {
    menu: true,
    sideRight: true,
    sideRight2: true,
    sideRight3: true,
    sideRight4: true,
    sideLeft: true,
    sideLeft2: true,
    sideLeft3: true,
    sideLeft4: true,
    counterFront: true,
    counterTop: true,
    partition1: true,
    partition2: true,
    totem: true,
    stele: true,
  };
}

function createSideZoneInstallations(): Pick<
  Record<DisplayWall, DisplayInstallation>,
  | "sideRight2"
  | "sideRight3"
  | "sideRight4"
  | "sideLeft2"
  | "sideLeft3"
  | "sideLeft4"
  | "partition1"
  | "partition2"
> {
  return {
    sideRight2: displayInstallation(),
    sideRight3: displayInstallation(),
    sideRight4: displayInstallation(),
    sideLeft2: displayInstallation(),
    sideLeft3: displayInstallation(),
    sideLeft4: displayInstallation(),
    partition1: displayInstallation(),
    partition2: displayInstallation(),
  };
}
