function displayInstallation(
  overrides: Partial<DisplayInstallation> = {},
): DisplayInstallation {
  const installation: DisplayInstallation = {
    displayCount: 0,
    displayLayers: 1,
    displaySize: STANDARD_DISPLAY_SIZE,
    orientation: "landscape",
    layout: "row",
    content: "menu",
    totemVariant: "halfTotem",
    positionOffset: [0, 0],
    selectedDisplayIndex: 0,
    displays: [],
    seamlessLEDSource: null,
    seamlessLEDSize: null,
    ...overrides,
  };
  installation.displayLayers = getTotemDisplayLayers(
    installation.totemVariant,
  );
  installation.displaySize = normalizeDisplaySize(
    installation.displaySize,
  );
  installation.displays = Array.from(
    { length: installation.displayCount * installation.displayLayers },
    () => ({
      displaySize: installation.displaySize,
      widthScale: 1,
      technology: "auto",
      orientation: installation.orientation,
      content: installation.content,
      networkMode: "own",
      networkPartner: null,
      networkSchedule: "allDay",
      networkShare: 30,
      positionOffset: [0, 0],
      position: null,
      defaultPosition: null,
    }),
  );
  return installation;
}

