  let openingShadowRefreshCount = 0;
  let scenePointerDownId = -1;
  let scenePointerDownX = 0;
  let scenePointerDownY = 0;
  let sceneManipulationMoved = false;
  let sceneSelectionGuardUntil = 0;
  const armSceneSelectionGuard = (
    reason: "drag" | "resize" | "ui",
    duration = 260,
  ): void => {
    sceneSelectionGuardUntil = performance.now() + duration;
    root.dataset.showroomSelectionGuard = reason;
    root.dataset.showroomSelectionGuardUntil = String(
      Math.round(sceneSelectionGuardUntil),
    );
    window.setTimeout(() => {
      if (performance.now() < sceneSelectionGuardUntil) return;
      delete root.dataset.showroomSelectionGuard;
      delete root.dataset.showroomSelectionGuardUntil;
    }, duration + 24);
  };
  const isSceneSelectionGuarded = (): boolean => (
    performance.now() < sceneSelectionGuardUntil
  );
  const invalidateOpeningShadowMap = (): void => {
    if (!renderer?.shadowMap.enabled) return;
    renderer.shadowMap.needsUpdate = true;
    openingShadowRefreshCount += 1;
    root.dataset.showroomOpeningShadowRefreshCount = String(
      openingShadowRefreshCount,
    );
  };
  root.dataset.showroomOpeningShadowRefreshCount = "0";
  let selectedStructureObject: Object3D | null = null;
  let selectedStructureWall: FreestandingWall | null = null;
  let selectedStructureSelectionIndex = -1;
  let structureSelectionHelper: BoxHelper | null = null;
  let selectedDisplayObject: Object3D | null = null;
  let displayFlyoutOpen = false;
  let displayPreviewOpen = false;
  let displayPreviewReturnFocus: HTMLElement | null = null;
  let selectedContentElementId: string | null = null;
  let contentElementSequence = 0;
