  let objectFlyoutOpen = false;
  let objectFlyoutAnchor: [number, number] = [0, 0];
  let selectionVisualTarget: Object3D | null = null;
  const dismissedStructureControls = new Set<string>();
  let activeStructureControlKey: string | null = null;
  let selectionAccentLight: PointLight | null = null;
  let selectionAccentPoint: Vector3 | null = null;
  let config: ShowroomConfig = { ...INITIAL_CONFIG };
  let selectionMode: SelectionMode = "auto";
  let guidedAddTechnology: DisplayTechnologyPreference | null = null;
  let restoreSeamlessLEDInstallation = (): boolean => false;
  let renderSelectionBrowser = (): void => {};
  const roomConfigurations = createRoomConfigurations();
  const savedRoomSnapshots: Partial<Record<RoomPreset, RoomConfiguration>> = {};
  const savedRoomPresets = new Set<RoomPreset>();
  const savedRoomEntries: SavedRoomEntry[] = [];
  try {
    const savedShowroom = JSON.parse(
      localStorage.getItem(SAVED_SHOWROOM_ROOMS_KEY) ?? "{}",
    ) as {
      selected?: Partial<ShowroomConfig>;
      rooms?: Partial<Record<RoomPreset, RoomConfiguration>>;
      entries?: SavedRoomEntry[];
    };
    Object.entries(savedShowroom.rooms ?? {}).forEach(([preset, room]) => {
      if (!(preset in roomConfigurations) || !room) return;
      const roomPreset = preset as RoomPreset;
      roomConfigurations[roomPreset] = room;
      savedRoomSnapshots[roomPreset] = room;
      savedRoomPresets.add(roomPreset);
    });
    (savedShowroom.entries ?? []).forEach((entry) => {
      if (
        !entry
        || typeof entry.id !== "string"
        || !(entry.preset in roomConfigurations)
        || !entry.room
      ) return;
      savedRoomEntries.push({
        ...entry,
        name: entry.name || PRESET_LABELS[entry.preset],
        preview: typeof entry.preview === "string" ? entry.preview : null,
        savedAt: entry.savedAt || new Date(0).toISOString(),
      });
      savedRoomPresets.add(entry.preset);
    });
    const savedPreset = savedShowroom.selected?.preset;
    if (savedPreset && savedPreset in roomConfigurations) {
      config = { ...config, ...savedShowroom.selected } as ShowroomConfig;
    }
    const activeSavedRoom = roomConfigurations[config.preset];
    config.roomSize = activeSavedRoom.roomSize;
    config.light = activeSavedRoom.light;
    config.brightness = activeSavedRoom.brightness;
    config.wall = activeSavedRoom.selectedWall;

    // Storage version 1 contained one snapshot per room. Promote those saves to
    // the new project library without losing existing customer configurations.
    if (savedRoomEntries.length === 0) {
      Object.entries(savedRoomSnapshots).forEach(([preset, room]) => {
        if (!room) return;
        const roomPreset = preset as RoomPreset;
        const installation = room.installations[room.selectedWall];
        savedRoomEntries.push({
          id: roomPreset,
          preset: roomPreset,
          name: PRESET_LABELS[roomPreset],
          room,
          config: {
            ...INITIAL_CONFIG,
            preset: roomPreset,
            roomSize: room.roomSize,
            light: room.light,
            brightness: room.brightness,
            wall: room.selectedWall,
            displayCount: installation.displayCount,
            displaySize: installation.displaySize,
            orientation: installation.orientation,
            content: installation.content,
            totemVariant: installation.totemVariant,
            selectedDisplayIndex: installation.selectedDisplayIndex,
          },
          preview: null,
          savedAt: new Date(0).toISOString(),
        });
      });
    }
  } catch {
    // A malformed or unavailable local store must never block the showroom.
  }
  // A room starts at the smallest size that contains its current equipment.
  // Explicit user choices may enlarge that result, but can never crop content.
  const manualRoomSizeOverrides = new Map<RoomPreset, RoomSize>(
    Array.from(savedRoomPresets, (preset) => [
      preset,
      roomConfigurations[preset].roomSize,
    ]),
  );
  let automaticMinimumRoomSize: RoomSize = config.roomSize;
  const networkPairKey = (
    first: RoomPreset,
    second: RoomPreset,
  ): string => [first, second].sort().join(":");
  let networkMembershipEnabled = true;
  const networkConnectionStatuses = new Map<
    string,
    NetworkConnectionStatus
  >([
    [networkPairKey("restaurant", "fitnessCenter"), "approved"],
    [networkPairKey("outdoorShop", "mountainStation"), "approved"],
    [networkPairKey("cinema", "cafe"), "approved"],
  ]);
