    const createPremiumPlant = (
      potMaterial: Material,
      leafMaterial: Material,
    ): Group => {
      const premiumPlant = new THREE.Group();
      const pot = new THREE.Mesh(
        new THREE.CylinderGeometry(0.34, 0.42, 0.62, 24),
        potMaterial,
      );
      pot.position.y = 0.31;
      pot.castShadow = true;
      premiumPlant.add(pot);
      const leafGeometry = new THREE.SphereGeometry(0.32, 12, 10);
      const leaves = new THREE.InstancedMesh(leafGeometry, leafMaterial, 7);
      const matrix = new THREE.Matrix4();
      const leafLayout: Array<[number, number, number, number, number]> = [
        [0, 0.95, 0, 0.62, 1.32],
        [-0.24, 1.25, 0.04, 0.52, 1.18],
        [0.25, 1.42, -0.05, 0.5, 1.2],
        [-0.1, 1.68, 0.12, 0.46, 1.08],
        [0.16, 1.9, -0.1, 0.42, 1],
        [-0.3, 1.8, -0.08, 0.4, 0.96],
        [0.32, 1.66, 0.1, 0.4, 0.92],
      ];
      leafLayout.forEach(([x, y, z, width, height], index) => {
        matrix.compose(
          new THREE.Vector3(x, y, z),
          new THREE.Quaternion().setFromEuler(
            new THREE.Euler(0, index * 0.78, index % 2 ? 0.32 : -0.28),
          ),
          new THREE.Vector3(width, height, 0.48),
        );
        leaves.setMatrixAt(index, matrix);
      });
      leaves.castShadow = true;
      leaves.instanceMatrix.needsUpdate = true;
      premiumPlant.add(leaves);
      return premiumPlant;
    };
    const addProductBottles = (
      group: Group,
      material: Material,
      positions: Array<[number, number, number]>,
    ): void => {
      const bottles = new THREE.InstancedMesh(
        new THREE.CylinderGeometry(0.07, 0.075, 0.32, 12),
        material,
        positions.length,
      );
      const matrix = new THREE.Matrix4();
      positions.forEach(([x, y, z], index) => {
        matrix.makeTranslation(x, y, z);
        bottles.setMatrixAt(index, matrix);
      });
      bottles.castShadow = true;
      bottles.instanceMatrix.needsUpdate = true;
      group.add(bottles);
    };

