  const renderRetailDisplayMotion = (
    context: CanvasRenderingContext2D,
    width: number,
    height: number,
    index: number,
    unit: DisplayUnitConfiguration,
    motionTime: number,
  ): void => {
    if (
      config.preset !== "fashionStore"
      && config.preset !== "electronicsStore"
      && config.preset !== "shoppingMall"
    ) return;
    const stories = RETAIL_DISPLAY_STORIES[config.preset][unit.content];
    const slideDuration = reducedMotion ? Number.POSITIVE_INFINITY : 4.4;
    const slideIndex = Number.isFinite(slideDuration)
      ? (Math.floor(motionTime / slideDuration) + index) % stories.length
      : index % stories.length;
    const progress = reducedMotion ? 0.56 : (motionTime / slideDuration) % 1;
    const fashion = config.preset === "fashionStore";
    const electronics = config.preset === "electronicsStore";
    const palette = fashion
      ? {
        background: "#201915",
        secondary: "#8b614e",
        accent: "#e5c89b",
        text: "#fffaf0",
        muted: "#d3c1ae",
      }
      : electronics
        ? {
          background: "#07131b",
          secondary: "#124c66",
          accent: "#68d6ff",
          text: "#f2fbff",
          muted: "#b5d6e2",
        }
        : {
          background: "#e8eef0",
          secondary: "#2d6373",
          accent: "#b26f52",
          text: "#17272d",
          muted: "#48626b",
        };
    const background = context.createLinearGradient(0, 0, width, height);
    background.addColorStop(0, palette.background);
    background.addColorStop(
      1,
      fashion ? "#604333" : electronics ? "#173849" : "#bfd4da",
    );
    context.globalAlpha = 0.64;
    context.fillStyle = background;
    context.fillRect(0, 0, width, height);
    context.globalAlpha = 1;

    context.globalAlpha = fashion ? 0.22 : 0.18;
    for (let shape = 0; shape < 7; shape += 1) {
      const x = width * (
        (shape * 0.18 + progress * (electronics ? 0.24 : 0.12)) % 1.2
      ) - width * 0.1;
      const y = height * (0.12 + shape % 3 * 0.28);
      context.fillStyle = shape % 2 ? palette.accent : palette.secondary;
      if (!fashion && !electronics) {
        context.fillRect(x, y, width * 0.13, height * 0.12);
      } else {
        context.beginPath();
        context.arc(x, y, width * (0.035 + shape % 2 * 0.018), 0, Math.PI * 2);
        context.fill();
      }
    }
    context.globalAlpha = 1;

    const left = width * 0.072;
    context.fillStyle = palette.accent;
    context.fillRect(
      left,
      height * 0.085,
      width * (0.19 + progress * 0.12),
      Math.max(5, height * 0.012),
    );
    context.fillStyle = palette.text;
    context.font = `700 ${Math.round(width * 0.029)}px Arial, sans-serif`;
    context.fillText(
      fashion
        ? "SWISSCOMPACT · FASHION"
        : electronics
          ? "SWISSCOMPACT · TECH"
          : "SWISSCOMPACT · CENTER",
      left,
      height * 0.18,
    );
    context.font = `850 ${Math.round(
      unit.orientation === "portrait" ? width * 0.09 : width * 0.062,
    )}px Arial, sans-serif`;
    const words = stories[slideIndex].split(" ");
    const lines: string[] = [];
    let line = "";
    words.forEach((word) => {
      const candidate = line ? `${line} ${word}` : word;
      if (context.measureText(candidate).width > width * 0.74 && line) {
        lines.push(line);
        line = word;
      } else {
        line = candidate;
      }
    });
    if (line) lines.push(line);
    lines.slice(0, 3).forEach((text, lineIndex) => {
      context.fillText(text, left, height * (0.43 + lineIndex * 0.12));
    });

    if (!fashion && !electronics && unit.content === "pickup") {
      const mapX = width * 0.66;
      const mapY = height * 0.7;
      context.strokeStyle = palette.accent;
      context.lineWidth = Math.max(4, width * 0.008);
      context.beginPath();
      context.moveTo(mapX - width * 0.1, mapY + height * 0.08);
      context.lineTo(mapX, mapY - height * 0.03);
      context.lineTo(mapX + width * 0.12, mapY + height * 0.04);
      context.stroke();
      context.beginPath();
      context.arc(mapX, mapY - height * 0.03, width * 0.018, 0, Math.PI * 2);
      context.fillStyle = palette.accent;
      context.fill();
    }
    context.fillStyle = palette.accent;
    context.fillRect(left, height * 0.81, width * 0.3, height * 0.014);
    context.fillStyle = palette.muted;
    context.font = `600 ${Math.round(width * 0.024)}px Arial, sans-serif`;
    context.fillText(
      fashion
        ? "Kollektion · Stil · Service"
        : electronics
          ? "Produkte · Vergleich · Beratung"
          : "Shops · Events · Orientierung",
      left,
      height * 0.89,
    );
    stories.forEach((_, dot) => {
      context.beginPath();
      context.arc(
        left + dot * width * 0.032,
        height * 0.955,
        dot === slideIndex ? width * 0.006 : width * 0.0035,
        0,
        Math.PI * 2,
      );
      context.fillStyle = dot === slideIndex
        ? palette.accent
        : fashion || electronics
          ? "rgba(255,255,255,.32)"
          : "rgba(20,45,52,.28)";
      context.fill();
    });
  };

