    const colors = presets[config.preset];
    setMaterialColor(roomMaterials.floor, colors.floor);
    setMaterialColor(roomMaterials.wall, colors.wall);
    setMaterialColor(roomMaterials.leftWall, colors.side);
    setMaterialColor(roomMaterials.rightWall, colors.side);
    roomMaterials.ceiling.color.copy(roomMaterials.wall.color);
    roomMaterials.ceiling.color.offsetHSL(0, -0.12, 0.22);
    setMaterialColor(roomMaterials.counter, colors.counter);
    setMaterialColor(roomMaterials.metal, colors.metal);
    setMaterialColor(roomMaterials.wood, colors.wood);
    setMaterialColor(roomMaterials.structureBody, colors.structureBody);
    setMaterialColor(roomMaterials.structureBase, colors.structureBase);
    setMaterialColor(roomMaterials.structureTrim, colors.structureTrim);
    roomMaterials.structureBody.emissive.set(colors.structureGlow);
    roomMaterials.structureTrim.emissive.set(colors.structureGlow);
    roomMaterials.floor.roughness = 0.76;
    roomMaterials.wall.roughness = 0.94;
    roomMaterials.leftWall.roughness = 0.8;
    roomMaterials.rightWall.roughness = 0.8;
    roomMaterials.ceiling.roughness = 0.92;
    roomMaterials.counter.roughness = 0.4;
    roomMaterials.metal.roughness = 0.2;
    roomMaterials.metal.metalness = 0.82;
    roomMaterials.wood.roughness = 0.54;
