    roomMaterials.structureBase.roughness = 0.18;
    roomMaterials.structureBase.metalness = 0.72;
    roomMaterials.structureTrim.roughness = 0.16;
    roomMaterials.structureTrim.metalness = 0.64;
    roomMaterials.structureTrim.emissiveIntensity = 0.28;
    Object.values(roomMaterials).forEach((material) => {
      material.needsUpdate = true;
    });
    applyRoomSurfaceConfiguration();
    objects.tables.visible = config.preset === "restaurant";
    objects.takeawayElements.visible = config.preset === "takeaway";
    objects.cafeElements.visible = config.preset === "cafe";
    objects.restaurantElements.visible = config.preset === "restaurant";
    objects.beautySalonElements.visible = config.preset === "beautySalon";
